const COLLECTION_MILESTONE_NAMES: Record<string, string> = {
  collection_first_shelf: 'First Shelf',
  collection_suit_sampler: 'Four Winds',
  collection_curator: "Curator's Eye",
  collection_wayfinder: 'Marked Routes',
  collection_many_roads: 'Many Roads Home',
  collection_citywide: 'Citywide Binder',
};

function collectionGoalSummary(account = loadAccount()) {
  const milestones = collectionMilestoneProgress(account);
  const next = milestones.find((milestone) => !milestone.complete);
  return {
    owned: Object.keys(account.cardCollection).length,
    total: Object.keys(cardLibrary).length,
    completed: milestones.filter((milestone) => milestone.complete).length,
    milestoneTotal: milestones.length,
    next: next ? {
      ...next,
      name: COLLECTION_MILESTONE_NAMES[next.id] ?? 'Collection Goal',
    } : null,
    allComplete: !next,
    optional: true,
    affectsPower: false,
    timeLimited: false,
    destination: 'Collection Atlas',
  };
}

type CollectionGoalStripModule = typeof import('./game/collection-goal-strip');
let collectionGoalStripModulePromise: Promise<CollectionGoalStripModule> | undefined;

function loadCollectionGoalStripModule() {
  collectionGoalStripModulePromise ??= import('./game/collection-goal-strip');
  return collectionGoalStripModulePromise;
}

function renderCollectionGoalStrip(
  scene: Phaser.Scene,
  x: number,
  y: number,
  width: number,
  name: string,
  onOpen: (cardId?: string) => void,
) {
  const goal = collectionGoalSummary();
  void loadCollectionGoalStripModule().then((module) => {
    if (!scene.sys.settings.active || scene.children.list.some((child) => child.name === name)) return;
    module.renderCollectionGoalStrip(scene, x, y, width, name, goal, onOpen, {
      addIcon: (target, iconX, iconY) => addUiIconImage(target, 'codex-medallion', iconX, iconY, 13),
      playConfirm: () => playUiSound('confirm'),
    });
    (scene as any).updateMenuTextState?.();
    (scene as any).updateTextState?.();
  });
}

function buttonIconForLabel(label: string): UiIconId | undefined {
  const normalized = label.toLowerCase();
  if (normalized === 'up') return 'scroll-up-chevron';
  if (normalized === 'down') return 'scroll-down-chevron';
  if (normalized.includes('back')) return 'back-chevron';
  if (normalized.includes('take this route')) return 'route-commit-medallion';
  if (normalized.includes('refresh') || normalized.includes('new stock')) return 'refresh-ring';
  if (normalized.includes('preen')) return 'preen-kit';
  if (normalized.includes('remove') || normalized.includes('release')) return 'release-card';
  if (normalized.includes('buy') || normalized.includes('market')) return 'market-basket';
  if (normalized.includes('settings')) return 'settings-medallion';
  if (normalized.includes('codex') || normalized.includes('collection')) return 'codex-medallion';
  if (normalized.includes('how to play') || normalized.includes('help')) return 'help-medallion';
  if (normalized.includes('flock record') || normalized.includes('record')) return 'record-medallion';
  if (normalized === 'start run' || normalized === 'start new run' || normalized === 'continue run') return 'start-run-medallion';
  return undefined;
}

function zoneIconForLabel(zone: string): UiIconId {
  if (zone === 'Discard') return 'discard-basket';
  if (zone === 'Cleared') return 'release-card';
  if (zone === 'Hand') return 'deck-stack';
  return 'draw-stack';
}

function roleIconForCard(card: Card | ActiveCardContract): UiIconId {
  if (card.role === 'attack') return 'release-card';
  if (card.role === 'skill') return 'cover-shield';
  return 'deck-stack';
}

function targetIconForTarget(target: TargetType): UiIconId {
  if (target === 'self') return 'flock-heart';
  if (target === 'none') return 'deck-stack';
  if (target === 'allEnemies') return 'release-card';
  if (target === 'choice') return 'route-pin';
  return 'release-card';
}

function statIconForKey(key: string): UiIconId | undefined {
  const term = key === 'openSkyGuard' ? 'Open Sky Guard'
    : key === 'wingbeats' ? 'Wingbeat'
      : `${key[0]?.toUpperCase()}${key.slice(1)}`;
  if (KEYWORDS[term]) return keywordIconId(term);
  if (key === 'damage') return 'release-card';
  if (key === 'moltPower') return 'preen-kit';
  return undefined;
}

function marketIconForKicker(kicker: string): UiIconId | undefined {
  const normalized = kicker.toLowerCase();
  if (normalized.includes('waymark')) return 'waymark-compass';
  if (normalized.includes('supply')) return 'supply-pouch';
  if (normalized.includes('preen')) return 'preen-kit';
  if (normalized.includes('remove') || normalized.includes('release')) return 'release-card';
  if (normalized.includes('refresh')) return 'refresh-ring';
  return undefined;
}






const MOTION_PREFERENCE_STORAGE_KEY = 'birdsquad.motionPreference';
const COMBAT_PACE_STORAGE_KEY = 'birdsquad.combatPace';
const ANIMATION_PACE_STORAGE_KEY = 'birdsquad.animationPace';
const TEXT_PACE_STORAGE_KEY = 'birdsquad.textPace';

function systemPrefersReducedMotion(): boolean {
  return typeof window !== 'undefined'
    && typeof window.matchMedia === 'function'
    && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

function motionPreference(): MotionPreference {
  if (typeof window === 'undefined') return 'system';
  const stored = safeStorageGet(MOTION_PREFERENCE_STORAGE_KEY);
  return stored === 'full' || stored === 'reduced' || stored === 'system' ? stored : 'system';
}

function setMotionPreference(value: MotionPreference) {
  if (typeof window === 'undefined') return;
  safeStorageSet(MOTION_PREFERENCE_STORAGE_KEY, value);
}

function motionState() {
  const preference = motionPreference();
  const systemReduced = systemPrefersReducedMotion();
  const reduced = preference === 'reduced' || (preference === 'system' && systemReduced);
  return { preference, reduced, systemReduced };
}

function currentScreenShakeState() {
  return screenShakeState(motionState().reduced);
}

function currentFlashEffectsState() {
  return flashEffectsState(motionState().reduced);
}

function combatPacePreference(): CombatPace {
  if (typeof window === 'undefined') return 'standard';
  const stored = safeStorageGet(COMBAT_PACE_STORAGE_KEY);
  return stored === 'cinematic' || stored === 'standard' || stored === 'snappy' ? stored : 'standard';
}

function setCombatPacePreference(value: CombatPace) {
  if (typeof window === 'undefined') return;
  safeStorageSet(COMBAT_PACE_STORAGE_KEY, value);
}

function combatPacingState() {
  return { preference: combatPacePreference() };
}

function animationPacePreference(): AnimationPace {
  if (typeof window === 'undefined') return 'standard';
  const stored = safeStorageGet(ANIMATION_PACE_STORAGE_KEY);
  return stored === 'relaxed' || stored === 'fast' ? stored : 'standard';
}

function animationPaceTimeScale(preference = animationPacePreference()) {
  if (preference === 'relaxed') return 0.8;
  if (preference === 'fast') return 1.3;
  return 1;
}

function animationPacingState(scene?: Phaser.Scene) {
  const preference = animationPacePreference();
  const timeScale = animationPaceTimeScale(preference);
  return {
    preference,
    timeScale,
    tweenTimeScale: scene?.tweens.timeScale ?? timeScale,
    spriteTimeScale: scene?.anims.globalTimeScale ?? timeScale,
  };
}

function syncSceneAnimationPace(scene: Phaser.Scene) {
  const timeScale = animationPaceTimeScale();
  scene.tweens.timeScale = timeScale;
  scene.anims.globalTimeScale = timeScale;
}

function setAnimationPacePreference(scene: Phaser.Scene, value: AnimationPace) {
  if (typeof window !== 'undefined') safeStorageSet(ANIMATION_PACE_STORAGE_KEY, value);
  syncSceneAnimationPace(scene);
}

function textPacePreference(): TextPace {
  if (typeof window === 'undefined') return 'standard';
  const stored = safeStorageGet(TEXT_PACE_STORAGE_KEY);
  return stored === 'relaxed' || stored === 'fast' ? stored : 'standard';
}

function textPaceScale(preference = textPacePreference()) {
  if (preference === 'relaxed') return 1.45;
  if (preference === 'fast') return 0.65;
  return 1;
}

function textPacingState() {
  const preference = textPacePreference();
  const holdScale = textPaceScale(preference);
  return {
    preference,
    holdScale,
    minimumReadableMs: Math.round(COMBAT_INTRO_MIN_DISMISS_MS * holdScale),
    calloutHoldMs: Math.round(380 * holdScale),
    bannerHoldMs: Math.round(520 * holdScale),
  };
}

function setTextPacePreference(value: TextPace) {
  if (typeof window !== 'undefined') safeStorageSet(TEXT_PACE_STORAGE_KEY, value);
  setFeedbackTextHoldScale(textPaceScale(value));
}

setFeedbackTextHoldScale(textPaceScale());

function prefersReducedMotion(): boolean {
  return motionState().reduced;
}

function stableMotionSeed(id: string): number {
  return [...id].reduce((sum, char) => sum + char.charCodeAt(0), 0);
}

// Which district the run is currently in + the run's seed. Scenes set these from
// RunState in init(); all map-relative reads go through currentMap(). The route
// graph is generated procedurally (deterministic per seed), so each run differs.
let activeMapIndex = 0;
let activeSeed = 'alpha';
const generatedMapCache = new Map<string, RuntimeRouteMap>();

function generatedMapFor(seed: string, mapIndex: number): RuntimeRouteMap {
  const blueprint = routeBlueprints[mapIndex] ?? routeBlueprints[0];
  const key = `${seed}:${mapIndex}`;
  let map = generatedMapCache.get(key);
  if (!map) {
    map = generateRouteMap(blueprint, hashSeed(seed, mapIndex));
    generatedMapCache.set(key, map);
  }
  return map;
}

function currentMap(): RuntimeRouteMap {
  return generatedMapFor(activeSeed, activeMapIndex);
}

function buildOutcomeFlightDetailsFor(summary: RunSummary, module: BossDossierModule) {
  const maps = runMapIndices(summary.runMode).map((mapIndex) => ({
    map: generatedMapFor(summary.seed, mapIndex),
    mapIndex,
  }));
  return module.buildOutcomeFlightDetails(summary, {
    maps,
    cardName: (id) => cardLibrary[id]?.name ?? id,
    routeNodeTypeLabel,
    waymarkName: (id) => alphaRouteMarkLibrary.get(id)?.name ?? id,
    supplyName: (id) => alphaSupplyLibrary.get(id)?.name ?? id,
    signalChoice: (signalId, choiceKey) => {
      const signal = alphaSignalLibrary.get(signalId);
      const choice = signal?.choices.find((candidate) => candidate.key === choiceKey);
      return `${signal?.title ?? signalId}: ${choice?.text ?? choiceKey}`;
    },
    difficultyLabel,
  });
}

function priceInBand(band: MarketPriceBand, rarityStep = 0, districtStep = activeMapIndex) {
  const scaled = band.base + rarityStep * 18 + districtStep * 8;
  return Math.round(clamp(scaled, band.min, band.max));
}

function runSupplyCapacity(runState: Pick<RunState, 'supplySlots'>) {
  return Math.max(BASE_SUPPLY_SLOTS, runState.supplySlots ?? BASE_SUPPLY_SLOTS);
}

